// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address queried, uint256 amountQueried, address caller, uint256 amountCaller) public {
        vm.assume(queried != address(0) && caller != address(0));
        vm.assume(queried != caller);
        amountQueried = bound(amountQueried, 1, 1 ether);
        amountCaller = bound(amountCaller, 1, 1 ether);
        vm.assume(amountQueried != amountCaller);

        vm.deal(queried, amountQueried);
        vm.prank(queried);
        c.addToBalance{value: amountQueried}();

        vm.deal(caller, amountCaller);
        vm.prank(caller);
        c.addToBalance{value: amountCaller}();

        vm.prank(caller);
        uint256 reported = c.getBalance(queried);

        assertTrue(reported == amountQueried);
    }
}
